package com.bank.interest.service;

import com.bank.interest.model.Account;
import jakarta.persistence.EntityManager;
import jakarta.persistence.PersistenceContext;
import lombok.extern.slf4j.Slf4j;
import org.springframework.stereotype.Service;
import org.springframework.transaction.annotation.Transactional;

import java.math.BigDecimal;
import java.math.RoundingMode;
import java.util.List;

@Service
@Slf4j
public class InterestPostingService {

    @PersistenceContext
    private EntityManager em;

    private static final BigDecimal RATE = new BigDecimal("0.04");
    private static final int CHUNK = 500;

    @Transactional
    public void postInterestForAll() {
        List<String> ids = em.createQuery("select a.id from Account a", String.class)
                             .getResultList();
        int processed = 0;
        for (String id : ids) {
            Account acct = em.find(Account.class, id);
            BigDecimal interest = acct.getBalance()
                    .multiply(RATE).setScale(2, RoundingMode.HALF_EVEN);
            acct.credit(interest);  // dirty checking will flush — no save() needed
            processed++;
            if (processed % CHUNK == 0) {
                em.flush();  // push buffered UPDATEs to the DB
                em.clear();  // detach ALL → reclaim memory for the next chunk
                log.info("Posted interest to {} accounts, context cleared", processed);
            }
        }
        em.flush();  // flush the final partial chunk
        log.info("Interest run complete: {} accounts", processed);
    }

    // Detach a SINGLE heavy object we no longer need, keeping the rest of the context
    @Transactional
    public void dropOne(Account heavy) {
        em.flush();         // make sure its pending changes are saved first
        em.detach(heavy);   // JPA single-entity detach (Hibernate: session.evict)
        log.info("Detached one entity; it is no longer dirty-checked");
    }
}
